class Solution:
    def encode(self, strs: list[str]) -> str:
        return '|'.join(strs)

    def decode(self, s: str) -> list[str]:
        if s == '':
            return ['']
        return s.split('|')

solutions.better:
class Solution:
    def encode(self, strs: list[str]) -> str:
        return '|'.join(w.replace('\\', '\\\\').replace('|', '\\|') for w in strs)

    def decode(self, s: str) -> list[str]:
        ans, cur, esc = [], [], False
        for ch in s:
            if esc:
                cur.append(ch); esc = False
            elif ch == '\\':
                esc = True
            elif ch == '|':
                ans.append(''.join(cur)); cur = []
            else:
                cur.append(ch)
        ans.append(''.join(cur))
        return ans

solutions.optimal:
class Solution:
    def encode(self, strs: list[str]) -> str:
        return ''.join(str(len(w)) + '#' + w for w in strs)

    def decode(self, s: str) -> list[str]:
        ans = []
        i = 0
        while i < len(s):
            j = i
            while s[j] != '#':
                j += 1
            length = int(s[i:j])
            start = j + 1
            ans.append(s[start:start+length])
            i = start + length
        return ans

